    static void FreshClassJourney(string phase){
        var p=FreshLoadSaved(true,true,true,true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);
        var list=new System.Collections.Generic.List<GameState>();foreach(int slot in new[]{1,2,3,0}){uint uid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));list.Add(FreshContributor(uid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}list.Add(p);var players=list.ToArray();Server.GamePool=players;Call(typeof(Revora.Database.JiangHu),"LoadClient",p);Require(players.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w)) && p.Entity.Class==25);


        var peer=FreshContributor(Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_warrior_peer_probe WHERE done")),"FreshWar1");Server.GamePool=players.Concat(new[]{peer}).ToArray();Require(!peer.Fake && peer.Account.State==AccountTable.AccountState.Player && peer.Entity.Class==20 && peer.Entity.Level>=130 && p.Entity.Level>=130);
        var type=Feature("LocalPkWar");var current=type.GetField("Current",Hidden).GetValue(null);var instance=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;DateTime start=new DateTime(2041,10,1,2,15,0,DateTimeKind.Utc),now=start;Require(start.AddHours(-7).DayOfWeek==DayOfWeek.Monday);Action<double> tick=minutes=>{now=start.AddMinutes(minutes);type.GetMethod("Tick",instance).Invoke(current,null);};
        if(phase.EndsWith("earn")){
            Require((bool)Sql("SELECT to_regclass('revora_fresh_class_probe') IS NULL") && FreshWarriorPeerSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_warrior_peer_probe WHERE done")) && !p.Entity.Dead && !peer.Entity.Dead && p.Inventory.Count<=34);
            type.GetField("clock",instance).SetValue(current,(Func<DateTime>)(()=>now));tick(0);FreshClassicTalk(p,1002,705,1);FreshClassicTalk(peer,1002,705,1);Require(p.Map.BaseID==1730 && p.Entity.MapID==peer.Entity.MapID);tick(15);ushort arena=p.Entity.MapID;p.Attackable=peer.Attackable=true;p.CantAttack=peer.CantAttack=Time32.Now.AddSeconds(-1);int hits=0;
            while(!peer.Entity.Dead && hits<300 && p.Entity.MapID==arena){p.Entity.X=peer.Entity.X;p.Entity.Y=(ushort)(peer.Entity.Y+1);p.Screen.Add(peer.Entity);peer.Screen.Add(p.Entity);p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=peer.Entity.UID,X=peer.Entity.X,Y=peer.Entity.Y,AttackType=Attack.Melee},p);hits++;}tick(15.02);
            Require((long)Sql("SELECT count(*) FROM revora_pk_wars WHERE run=@run AND state='complete' AND winner=@uid AND valuable_reward","run",FreshClassRun,"uid",(long)p.Entity.UID)==1 && (long)Sql("SELECT count(*) FROM revora_pk_entries WHERE run=@run AND competitive AND admitted_at IS NOT NULL","run",FreshClassRun)==2 && (long)Sql("SELECT count(*) FROM revora_pk_claims WHERE run=@run","run",FreshClassRun)==0 && p.Entity.MapID==1002 && peer.Entity.MapID==1002);
            if(peer.Entity.Dead){peer.Entity.DeathStamp=Time32.Now.AddSeconds(-20);GeneralData.Revive(new Data(true){UID=peer.Entity.UID,ID=Data.Revive},peer);}Require(!peer.Entity.Dead);Sql("CREATE TABLE revora_fresh_class_probe(stage int,hits int,items bigint[],snapshot text);INSERT INTO revora_fresh_class_probe VALUES(0,@hits,ARRAY[]::bigint[],NULL)","hits",hits);FreshClassSave(p,players,peer,1);
        }else{
            Require(FreshClassSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_class_probe")));int stage=(int)Sql("SELECT stage FROM revora_fresh_class_probe");type.GetField("clock",instance).SetValue(current,(Func<DateTime>)(()=>now));now=start.AddMinutes(16);
