                Require(stage==1);uint cp=p.Entity.ConquerPoints,rvp=p.Entity.RevoraPoint;ulong gold=p.Entity.Money;var old=p.Inventory.Objects.Select(i=>i.UID).ToArray();HeartTalk(p,705,3);var added=p.Inventory.Objects.Where(i=>!old.Contains(i.UID)).ToArray();Require(added.Length==6 && added.All(i=>i.Bound && i.Days==0) && added.Count(i=>i.ID==722136)==5 && added.Count(i=>ConquerItemInformation.BaseInformations[i.ID].PurificationLevel==7)==1 && p.Entity.ConquerPoints==cp+50000 && p.Entity.RevoraPoint==rvp+500 && p.Entity.Money==gold+500000);Sql("UPDATE revora_fresh_class_probe SET items=@items","items",added.Select(i=>(long)i.UID).ToArray());HeartTalk(peer,705,0);FreshClassSave(p,players,peer,2);
            }else Require(phase.EndsWith("reload") && stage==2);
            var rewards=(long[])Sql("SELECT items FROM revora_fresh_class_probe");var loaded=p.Inventory.Objects.Where(i=>rewards.Contains((long)i.UID)).ToArray();Require(rewards.Length==6 && rewards.All(id=>p.Inventory.ContainsUID((uint)id)) && loaded.All(i=>i.Bound && i.Days==0) && loaded.Count(i=>i.ID==722136)==5 && loaded.Count(i=>ConquerItemInformation.BaseInformations[i.ID].PurificationLevel==7)==1);string saved=FreshClassSnapshot(p,players,peer);foreach(var who in new[]{p,peer}){HeartTalk(who,705,3);HeartTalk(who,705,3);}Require(saved==FreshClassSnapshot(p,players,peer));
        }
        Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=11131 AND source='class-pk-v1' AND source_key=@run","uid",(long)p.Entity.UID,"run",FreshClassRun)==1 && FreshClassSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_class_probe")));System.Console.WriteLine("[career-process] "+phase+"-passed hits="+Sql("SELECT hits FROM revora_fresh_class_probe"));System.Console.Out.Flush();Environment.Exit(0);
    }
}
